#include <iostream>
#include <vector>
#include <cstdlib>
#define MAX 100500

using namespace std;

int main(void) {
    int n, m;
    long long int N;

    while (cin >> n >> m) {
        vector<long long int> d(n + 1, 0); // Initialize d with size n + 1 for easier prefix sum calculation
        long long int sum = 0, now = 0;

        // Read all N values in one loop for better cache efficiency
        for (int i = 1; i < n; i++) {
            cin >> N;
            d[i] = d[i - 1] + N; // Build prefix sum array
        }

        // Use a single vector to read M values
        vector<long long int> M(m);
        for (int i = 0; i < m; i++) {
            cin >> M[i];
        }

        // Calculate the sum in a single pass
        for (int i = 0; i < m; i++) {
            sum += (M[i] >= 0) ? (d[now + M[i]] - d[now]) : abs(d[now] - d[now + M[i]]);
            now += M[i];
        }

        cout << sum % 100000 << endl;
    }

    return 0;
}

